const blends=[{name:'Carrot Glow',word:'Carrot',tag:'MEET YOUR DAILY GLOW',description:'A little sunshine<br>in a bottle.',color:'#f3a276',img:'carrot.png',detail:'Carrot · Ginger',price:6.50},{name:'Beet Boost',word:'Beet',tag:'ROOT FOR THE BOLD',description:'A bright little<br>beet of joy.',color:'#c8879b',img:'beet.png',detail:'Beetroot · Greens',price:6.50},{name:'Green Garden',word:'Green',tag:'GOODNESS GROWS HERE',description:'The greener side<br>of delicious.',color:'#a9c78b',img:'green.png',detail:'Cucumber · Celery',price:6.50},{name:'Golden Harvest',word:'Golden',tag:'A GOLDEN KIND OF DAY',description:'Your daily dose<br>of bright.',color:'#e6bf65',img:'gold.png',detail:'Pepper · Turmeric',price:6.50}];let current=0;let cart={};try{cart=JSON.parse(localStorage.getItem('rr-cart')||'{}')}catch{}const $=s=>document.querySelector(s);const stage=$('#stage');function showSlide(i){current=(i+blends.length)%blends.length;const b=blends[current];document.documentElement.style.setProperty('--bg',b.color);$('#heroWord').textContent=b.word;$('#heroImage').src='assets/'+b.img;$('#heroImage').alt=b.name+' vegetable juice with fresh ingredients';$('#heroTag').textContent=b.tag;$('#heroDescription').innerHTML=b.description;$('#slideNumber').textContent=String(current+1).padStart(2,'0');$('#progress').style.width=((current+1)*25)+'%';document.querySelectorAll('[data-slide]').forEach((el,n)=>{el.classList.toggle('active',n===current);el.setAttribute('aria-current',n===current?'true':'false')});stage.classList.remove('changing');void stage.offsetWidth;stage.classList.add('changing')};document.querySelectorAll('[data-slide]').forEach(el=>el.addEventListener('click',()=>showSlide(+el.dataset.slide)));$('#prev').onclick=()=>showSlide(current-1);$('#next').onclick=()=>showSlide(current+1);let startX=0;stage.addEventListener('touchstart',e=>startX=e.touches[0].clientX,{passive:true});stage.addEventListener('touchend',e=>{let d=e.changedTouches[0].clientX-startX;if(Math.abs(d)>50)showSlide(current+(d<0?1:-1))},{passive:true});document.addEventListener('keydown',e=>{if(document.activeElement.matches('input,textarea'))return;if(e.key==='ArrowRight')showSlide(current+1);if(e.key==='ArrowLeft')showSlide(current-1);if(e.key==='Escape')closeCart()});$('#productGrid').innerHTML=blends.map((b,i)=>`<article class="product-card"><div class="visual" style="background:${b.color}"><img src="assets/${b.img}" alt="${b.name} juice bottle with vegetables" loading="lazy"></div><div class="product-info"><div><h3>${b.name}</h3><p>${b.detail}</p><span class="price">$${b.price.toFixed(2)}</span></div><button class="add" data-add="${i}" aria-label="Add ${b.name} to cart">+</button></div></article>`).join('');function renderCart(){let entries=Object.entries(cart).filter(([i,q])=>q>0);$('#cartCount').textContent=entries.reduce((n,[i,q])=>n+q,0);$('#cartItems').innerHTML=entries.length?entries.map(([i,q])=>`<div class="cart-row"><div><h3>${blends[i].name}</h3><span>$${blends[i].price.toFixed(2)} × ${q}</span></div><button data-remove="${i}">Remove one</button></div>`).join(''):'<p>Your cart is feeling a little empty. Let’s fix that.</p>';$('#subtotal').textContent='$'+entries.reduce((n,[i,q])=>n+blends[i].price*q,0).toFixed(2);localStorage.setItem('rr-cart',JSON.stringify(cart))}function openCart(){$('#scrim').hidden=false;$('#cartDrawer').classList.add('open');$('#cartDrawer').setAttribute('aria-hidden','false');$('#cartClose').focus()}function closeCart(){$('#scrim').hidden=true;$('#cartDrawer').classList.remove('open');$('#cartDrawer').setAttribute('aria-hidden','true')}document.addEventListener('click',e=>{let a=e.target.closest('[data-add]'),r=e.target.closest('[data-remove]');if(a){let i=a.dataset.add;cart[i]=(cart[i]||0)+1;renderCart();openCart()}if(r){cart[r.dataset.remove]--;renderCart()}});$('#cartOpen').onclick=openCart;$('#cartClose').onclick=closeCart;$('#continueShopping').onclick=closeCart;$('#scrim').onclick=closeCart;$('#newsletterForm').onsubmit=e=>{e.preventDefault();$('#newsletterMessage').textContent='Thanks for stopping by! This is a demo signup.'};showSlide(0);renderCart();
